class Solution {
    public int[][] seePeople(int[][] heights) {
        int r = heights.length, c = heights[0].length;
        int[][] res = new int[r][c];
        for (int i = 0; i < r; i++) {
            ArrayDeque<Integer> st = new ArrayDeque<>();
            for (int j = c - 1; j >= 0; j--) {
                boolean equal = false;
                while (!st.isEmpty() && st.peek() <= heights[i][j]) {
                    if (st.peek() == heights[i][j]) equal = true;
                    st.pop();
                    res[i][j]++;
                }
                if (!st.isEmpty() && !equal) res[i][j]++;
                st.push(heights[i][j]);
            }
        }
        for (int j = 0; j < c; j++) {
            ArrayDeque<Integer> st = new ArrayDeque<>();
            for (int i = r - 1; i >= 0; i--) {
                boolean equal = false;
                while (!st.isEmpty() && st.peek() <= heights[i][j]) {
                    if (st.peek().intValue() == heights[i][j]) equal = true;
                    st.pop();
                    res[i][j]++;
                }
                if (!st.isEmpty() && !equal) res[i][j]++;
                st.push(heights[i][j]);
            }
        }
        return res;
    }
}
